<?php require_once __DIR__.'/../config/config.php';header('Content-Type: application/json; charset=utf-8');function out($s,$x){http_response_code($s);echo json_encode($x,JSON_UNESCAPED_UNICODE);exit;}if(!logged())out(401,['success'=>false,'error'=>'Authentication required']);$method=$_SERVER['REQUEST_METHOD']??'GET';try{$pdo=db();if($method==='GET'){$id=(int)($_GET['id']??0);if($id){$s=$pdo->prepare('SELECT * FROM students WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)out(404,['success'=>false,'error'=>'Student not found']);out(200,['success'=>true,'data'=>$r]);}$q=trim($_GET['q']??'');$limit=min(100,max(1,(int)($_GET['limit']??25)));$page=max(1,(int)($_GET['page']??1));$offset=($page-1)*$limit;if($q){$like="%$q%";$s=$pdo->prepare('SELECT * FROM students WHERE student_code LIKE ? OR first_name LIKE ? OR last_name LIKE ? OR email LIKE ? OR class_name LIKE ? ORDER BY created_at DESC LIMIT '.$limit.' OFFSET '.$offset);$s->execute([$like,$like,$like,$like,$like]);}else{$s=$pdo->query('SELECT * FROM students ORDER BY created_at DESC LIMIT '.$limit.' OFFSET '.$offset);}$rows=$s->fetchAll();out(200,['success'=>true,'data'=>$rows,'meta'=>['page'=>$page,'limit'=>$limit]]);}if(!in_array($method,['POST','PUT','PATCH','DELETE'],true)){header('Allow: GET, POST, PUT, PATCH, DELETE');out(405,['success'=>false,'error'=>'Method not allowed']);}$token=(string)($_SERVER['HTTP_X_CSRF_TOKEN']??'');if(!hash_equals(csrf(),$token))out(419,['success'=>false,'error'=>'Invalid CSRF token']);$in=json_decode(file_get_contents('php://input'),true);if(!is_array($in))$in=$_POST;if($method==='DELETE'){$id=(int)($_GET['id']??$in['id']??0);$s=$pdo->prepare('DELETE FROM students WHERE id=?');$s->execute([$id]);out($s->rowCount()?200:404,['success'=>(bool)$s->rowCount(),'message'=>'Delete processed']);}$keys=['student_code','first_name','last_name','email','phone','gender','date_of_birth','class_name','section_name','admission_date','guardian_name','guardian_phone','address','status','notes'];foreach(['student_code','first_name','last_name','email','class_name'] as $k)if(trim((string)($in[$k]??''))==='')out(422,['success'=>false,'error'=>"$k is required"]);if(!filter_var($in['email'],FILTER_VALIDATE_EMAIL))out(422,['success'=>false,'error'=>'Valid email required']);$d=[];foreach($keys as $k)$d[$k]=trim((string)($in[$k]??''))?:null;$d['status']=$d['status']?:'Active';if(!in_array($d['status'],['Active','Inactive','Graduated','Transferred'],true))out(422,['success'=>false,'error'=>'Invalid status']);$id=(int)($in['id']??$_GET['id']??0);$s=$pdo->prepare('SELECT id FROM students WHERE (student_code=? OR email=?) AND id<>?');$s->execute([$d['student_code'],$d['email'],$id]);if($s->fetch())out(409,['success'=>false,'error'=>'Student ID or email already exists']);if($id){$set=implode(',',array_map(fn($k)=>"$k=?",array_keys($d)));$v=array_values($d);$v[]=$id;$pdo->prepare("UPDATE students SET $set WHERE id=?")->execute($v);out(200,['success'=>true,'message'=>'Student updated','id'=>$id]);}$pdo->prepare('INSERT INTO students('.implode(',',array_keys($d)).') VALUES('.implode(',',array_fill(0,count($d),'?')).')')->execute(array_values($d));out(201,['success'=>true,'message'=>'Student created','id'=>(int)$pdo->lastInsertId()]);}catch(Throwable $e){out(500,['success'=>false,'error'=>'Server/database error. Check configuration.']);}